fn removeElement(nums: &mut Vec<i32>, val: i32) -> usize {
    let mut write_idx = 0;
    let len = nums.len();

    for read_idx in 0..len {
        // Read the current element
        let x = nums[read_idx];
        // If it's not the target, write it at write_idx and advance write_idx
        if x != val {
            nums[write_idx] = x;
            write_idx += 1;
        }
    }

    // write_idx is the new length of the prefix without `val`
    write_idx
}

